          stack.push({ name: next, i: 0 })
        }
      } else {
        state.set(frame.name, 2)
        stack.pop()
      }
    }
  }
  return null
}

/**
 * Walk a DAG bottom-up (neighbors before the node itself) with an explicit
 * stack, so arbitrarily deep chains cannot overflow the call stack.
 * `combine(name, neighbors, value)` folds a node's own data with the
 * already-computed values of its neighbors.
 */
function foldBottomUp(names, adj, combine) {
  const value = new Map()
  for (const start of names) {
    if (value.has(start)) continue
    const stack = [{ name: start, i: 0 }]
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const neighbors = adj.get(frame.name)
      if (frame.i < neighbors.length) {
        const next = neighbors[frame.i++]
        if (!value.has(next)) stack.push({ name: next, i: 0 })
      } else {
        value.set(frame.name, combine(frame.name, neighbors, value))
        stack.pop()
      }
    }
  }
  return value
}

/**
 * Verify the graph is acyclic, raising the exit-3 cycle error described in
 * the specification when it is not.
 */
export function checkAcyclic({ names, adj }) {
  const cycle = findCycle(names, adj)
  if (cycle) throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
}

/**
 * Compute each task's wave (its depth in the dependency DAG), start and
 * finish time, plus the overall makespan with unlimited workers.
 */
export function computeTimes({ names, costs, adj }) {
  const depth = foldBottomUp(names, adj, (_name, deps, value) => {
    let d = 0
    for (const dep of deps) d = Math.max(d, value.get(dep) + 1)
    return d
  })
  const finish = foldBottomUp(names, adj, (name, deps, value) => {
    let start = 0n
    for (const dep of deps) if (value.get(dep) > start) start = value.get(dep)
    return start + costs.get(name)
  })
  const start = new Map()
  for (const name of names) start.set(name, finish.get(name) - costs.get(name))

  let makespan = 0n
  for (const f of finish.values()) if (f > makespan) makespan = f

  return { depth, start, finish, makespan }
}

