{"file_path":"src/merge.js","content":"import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * Reconstructs one side's version of a region by applying only that side's
 * own changes to the base slice, leaving the lines it did not touch as they
 * were in the base.
 */
function buildSideLines(base, regionStart, regionEnd, changes) {
  const lines = []
  let pointer = regionStart
  for (const change of changes) {
    lines.push(...base.slice(pointer, change.baseStart))
    lines.push(...change.lines)
    pointer = change.baseEnd
  }
  lines.push(...base.slice(pointer, regionEnd))
  return lines
}

/**
 * Resolves a region touched by one or more changes into its merged lines,
 * following the precedence: identical changes win, then an unchanged side
 * defers to the other, and otherwise the region conflicts.
 */
function resolveRegion(base, region) {
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  const mineLines = mineChanges.length ? buildSideLines(base, region.baseStart, region.baseEnd, mineChanges) : baseLines
  const theirsLines = theirsChanges.length
    ? buildSideLines(base, region.baseStart, region.baseEnd, theirsChanges)
    : baseLines

  if (arraysEqual(mineLines, theirsLines)) {
    const kind = mineChanges.length && theirsChanges.length ? 'both' : mineChanges.length ? 'mine' : 'theirs'
    return { kind, lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { kind: 'theirs', lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { kind: 'mine', lines: mineLines }
  }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * Splits the base document into stable and changed regions by merging
 * mine's and theirs's changes against it, then resolving each changed
 * region against the other two documents.
 */
export function buildRegions(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine).map(c => ({ ...c, side: 'mine' }))
  const theirsChanges = computeChanges(base, theirs).map(c => ({ ...c, side: 'theirs' }))
  const allChanges = mineChanges.concat(theirsChanges).sort((a, b) => a.baseStart - b.baseStart)

  const grouped = []
  let i = 0
  while (i < allChanges.length) {
    const region = { baseStart: allChanges[i].baseStart, baseEnd: allChanges[i].baseEnd, changes: [allChanges[i]] }
    i++
    while (i < allChanges.length && allChanges[i].baseStart <= region.baseEnd) {
      region.baseEnd = Math.max(region.baseEnd, allChanges[i].baseEnd)
      region.changes.push(allChanges[i])
      i++
    }
    grouped.push(region)
  }

  const results = []
  let cursor = 0
  for (const region of grouped) {
    if (region.baseStart > cursor) {
      results.push({ kind: 'stable', lines: base.slice(cursor, region.baseStart) })
    }
    const resolved = resolveRegion(base, region)
    results.push(resolved)
    cursor = region.baseEnd
  }
  if (cursor < base.length) {
    results.push({ kind: 'stable', lines: base.slice(cursor, base.length) })
  }
  return results
}
"}

