{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260927T230048Z/cell-362a9D/src/sheet.js","content":"/** Parsing of the sheet format read from standard input. */

import { parseAddress } from './address.js'

export class SheetError extends Error {}

/**
 * Parse sheet text into a Map from canonical address ("A1") to
 * `{ content, col, row }`. Throws a SheetError (message without the
 * `error: ` prefix) on the first invalid address or duplicate cell.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const stripped = line.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const m = /^([^ \t]+)([ \t]*)([\s\S]*)$/.exec(stripped)
    const rawAddress = m[1]
    let content = m[3]
    if (m[2] === '') {
      // no separator run: nothing follows the address
      content = ''
    }

    const parsed = parseAddress(rawAddress)
    if (!parsed.inRange) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${rawAddress}`)
    }
    if (cells.has(parsed.address)) {
      throw new SheetError(`line ${lineNo}: cell ${parsed.address} is declared twice`)
    }
    cells.set(parsed.address, { content, col: parsed.col, row: parsed.row })
  }
  return cells
}
"}

