{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260927T230048Z/cell-362a9D/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { evaluateSheet, collectDeps } from './evaluator.js'
import { formatValue } from './values.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'values' && mode !== 'deps') {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const input = readStdin()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }

  const lines = []
  if (mode === 'values') {
    for (const [address, value] of evaluateSheet(cells)) {
      lines.push(`${address}=${formatValue(value)}`)
    }
  } else {
    for (const [address, deps] of collectDeps(cells)) {
      const suffix = deps.map((d) => ` ${d}`).join('')
      lines.push(`${address}:${suffix}`)
    }
  }
  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

