{"file_path":"src/parse.js","content":"import { lineError, unknownTaskError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses a build graph from raw input text.
 *
 * Returns `{ tasks, deps }` where `tasks` maps a task name to its cost and
 * `deps` maps a task name to the `Set` of names it depends on. Every name
 * used anywhere is guaranteed to be a key of `tasks`.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  // Every name reference from a `dep` line, in the order it was written,
  // used to report the first unknown name in input order once parsing ends.
  const depReferences = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw lineError(lineNumber, 'expected task <name> <cost>')
      const [, name, cost] = words
      if (!NAME_RE.test(name)) throw lineError(lineNumber, `invalid task name ${name}`)
      if (!COST_RE.test(cost)) throw lineError(lineNumber, 'cost must be a non-negative integer')
      if (tasks.has(name)) throw lineError(lineNumber, `task ${name} is declared twice`)
      tasks.set(name, Number.parseInt(cost, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) throw lineError(lineNumber, 'expected dep <name> <dependency>...')
      const names = words.slice(1)
      for (const name of names) {
        if (!NAME_RE.test(name)) throw lineError(lineNumber, `invalid task name ${name}`)
      }
      const [head, ...rest] = names
      depReferences.push(head, ...rest)
      if (!deps.has(head)) deps.set(head, new Set())
      const set = deps.get(head)
      for (const dep of rest) set.add(dep)
    } else {
      throw lineError(lineNumber, `unknown directive ${directive}`)
    }
  }

  for (const name of depReferences) {
    if (!tasks.has(name)) throw unknownTaskError(name)
  }

  return { tasks, deps }
}
"}

