{"file_path":"src/graph.js","content":"import { cycleError } from './errors.js'

/**
 * Builds the dependents map (the reverse of `deps`): for every task, the
 * set of tasks that name it as a dependency.
 */
function buildDependents(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, new Set())
  for (const [name, set] of deps) {
    for (const dep of set) dependents.get(dep).add(name)
  }
  return dependents
}

/**
 * Walks the graph depth-first, starting from each task in ascending name
 * order and visiting each task's dependencies in ascending name order, and
 * throws the first cycle such a search finds. Doing this up front means
 * every later computation can assume the graph is acyclic.
 */
function checkAcyclic(tasks, deps) {
  const sortedNames = [...tasks.keys()].sort()
  const visited = new Set()
  const stack = []
  const onStack = new Set()

  function visit(name) {
    stack.push(name)
    onStack.add(name)
    const sortedDeps = [...(deps.get(name) ?? [])].sort()
    for (const dep of sortedDeps) {
      if (onStack.has(dep)) {
        const start = stack.indexOf(dep)
        throw cycleError([...stack.slice(start), dep])
      }
      if (!visited.has(dep)) visit(dep)
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
  }

  for (const name of sortedNames) {
    if (!visited.has(name)) visit(name)
  }
}

/**
 * Computes, for every task, its depth (the wave it sits in), start time and
 * finish time, per the specification: start is the greatest finish among
 * its dependencies (0 when it has none), finish is start plus cost, and
 * depth is 0 when it has no dependency or one more than the greatest depth
 * among its dependencies.
 */
function computeTimings(tasks, deps) {
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const cost = tasks.get(name)
    const depSet = deps.get(name) ?? new Set()
    if (depSet.size === 0) {
      depth.set(name, 0)
      start.set(name, 0)
    } else {
      let maxDepth = 0
      let maxFinish = 0
      for (const dep of depSet) {
        compute(dep)
        maxDepth = Math.max(maxDepth, depth.get(dep))
        maxFinish = Math.max(maxFinish, finish.get(dep))
      }
      depth.set(name, maxDepth + 1)
      start.set(name, maxFinish)
    }
    finish.set(name, start.get(name) + cost)
  }

  for (const name of tasks.keys()) compute(name)

  return { depth, start, finish }
}

/**
 * Computes, for every task, the cost of the longest chain that begins at
 * it and runs down through its dependents to a task nothing depends on.
 * This is the priority `pack` uses to choose among ready tasks.
 */
function computePriorities(tasks, dependents) {
  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    const cost = tasks.get(name)
    const outgoing = dependents.get(name)
    let best = 0
    for (const dependent of outgoing) best = Math.max(best, compute(dependent))
    const value = cost + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Validates the graph is acyclic and returns every derived structure the
 * three commands need: dependents, depth/start/finish per task, and the
 * pack scheduling priority per task.
 */
export function analyzeGraph(tasks, deps) {
  checkAcyclic(tasks, deps)
  const dependents = buildDependents(tasks, deps)
  const { depth, start, finish } = computeTimings(tasks, deps)
  const priority = computePriorities(tasks, dependents)
  return { deps, dependents, depth, start, finish, priority }
}
"}

