{"file_path":"src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers.
 *
 * Returns `{ logs, makespan }` where `logs[i]` is the ordered list of
 * `{ name, start, finish }` entries worker `i` ran.
 */
export function pack(tasks, deps, priority, workerCount) {
  const freeAt = new Array(workerCount).fill(0)
  const logs = Array.from({ length: workerCount }, () => [])
  const started = new Set()
  const finishOf = new Map()
  const names = [...tasks.keys()]
  let remaining = names.length
  let time = 0
  let makespan = 0

  const isReady = (name) => {
    const depSet = deps.get(name) ?? new Set()
    for (const dep of depSet) {
      if ((finishOf.get(dep) ?? Infinity) > time) return false
    }
    return true
  }

  while (remaining > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      const freeWorker = freeAt.findIndex((t) => t <= time)
      if (freeWorker === -1) break

      let best = null
      for (const name of names) {
        if (started.has(name) || !isReady(name)) continue
        if (best === null || priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)) {
          best = name
        }
      }
      if (best === null) break

      const cost = tasks.get(best)
      const start = time
      const finish = start + cost
      freeAt[freeWorker] = finish
      started.add(best)
      finishOf.set(best, finish)
      logs[freeWorker].push({ name: best, start, finish })
      makespan = Math.max(makespan, finish)
      remaining -= 1
      progressed = true
    }

    if (remaining > 0) {
      time = Math.min(...freeAt.filter((t) => t > time))
    }
  }

  return { logs, makespan }
}
"}

