{"file_path":"src/reports.js","content":"/**
 * Renders the `waves` report: one line per wave in ascending order followed
 * by the total makespan.
 */
export function renderWaves(tasks, { depth, finish }) {
  const byDepth = new Map()
  for (const name of tasks.keys()) {
    const d = depth.get(name)
    if (!byDepth.has(d)) byDepth.set(d, [])
    byDepth.get(d).push(name)
  }

  const maxDepth = tasks.size === 0 ? -1 : Math.max(...depth.values())
  const lines = []
  for (let d = 0; d <= maxDepth; d++) {
    const names = (byDepth.get(d) ?? []).sort()
    lines.push(`wave ${d}: ${names.join(' ')}`)
  }

  const total = tasks.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

/**
 * Renders the `explain` report: one line per task in ascending name order
 * followed by the total makespan.
 */
export function renderExplain(tasks, { depth, start, finish }) {
  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }
  const total = tasks.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

/**
 * Renders the `pack` report: one line per worker in index order followed
 * by the makespan.
 */
export function renderPack({ logs, makespan }) {
  const lines = logs.map((entries, i) => {
    const parts = entries.map(({ name, start, finish }) => ` ${name}@${start}-${finish}`)
    return `worker ${i}:${parts.join('')}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}
"}

