{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { tokenize, LexError } from './lexer.js'

const KIND_ORDER = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const mode = args[0]
  const source = readFileSync(0, 'utf8')

  let tokens
  try {
    tokens = tokenize(source)
  } catch (e) {
    if (e instanceof LexError) {
      process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }

  if (mode === 'tokens') {
    const lines = tokens.map((t) => {
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.value) : t.text
      return `${t.line}:${t.col} ${t.kind} ${body}`
    })
    process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
  } else {
    const counts = Object.fromEntries(KIND_ORDER.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind]++
    const lines = KIND_ORDER.map((k) => `${k} ${counts[k]}`)
    lines.push(`total ${tokens.length}`)
    process.stdout.write(lines.join('\n') + '\n')
  }
  process.exit(0)
}

main()
"}

