{"file_path":"src/router.js","content":"/**
 * Resolves each event key to the policies on the longest matching route
 * prefix, or to no policies at all when no route matches.
 */

/**
 * @param {string} key
 * @param {Array<{ prefix: string, policies: Array }>} routes
 * @returns {Array} the policies for the best matching route, or `[]`
 */
export function resolveRoute(key, routes) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === null || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best === null ? [] : best.policies
}
"}

{"file_path":"src/simulate.js","content":"/**
 * Replays a parsed event log against its routed policies, producing one
 * verdict per event in log order.
 */

import { resolveRoute } from './router.js'

/**
 * @param {{ routes: Array, events: Array<{ tick: bigint, key: string }> }} parsed
 * @returns {Array<{ tick: bigint, key: string, allowed: boolean, deniedBy: string|null }>}
 */
export function simulate({ routes, events }) {
  const verdicts = []
  for (const { tick, key } of events) {
    const policies = resolveRoute(key, routes)

    for (const policy of policies) policy.advance(key, tick)

    let deniedBy = null
    for (const policy of policies) {
      if (!policy.allow(key)) {
        deniedBy = policy.name
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of policies) policy.record(key, tick)
    }

    verdicts.push({ tick, key, allowed: deniedBy === null, deniedBy })
  }
  return verdicts
}
"}

{"file_path":"src/report.js","content":"/**
 * Renders simulation verdicts into the `replay` and `summary` output
 * formats.
 */

/** One `<tick> <key> allow|deny <policy>` line per event, in log order. */
export function renderReplay(verdicts) {
  return verdicts
    .map(({ tick, key, allowed, deniedBy }) =>
      allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${deniedBy}`
    )
    .join('')
}

/**
 * One `<key> allowed=<a> denied=<d>` line per key that saw an event, in
 * ascending key order, followed by the `total allowed=<a> denied=<d>` line.
 */
export function renderSummary(verdicts) {
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (const { key, allowed } of verdicts) {
    let counts = perKey.get(key)
    if (!counts) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(key, counts)
    }
    if (allowed) {
      counts.allowed++
      totalAllowed++
    } else {
      counts.denied++
      totalDenied++
    }
  }

  const lines = []
  for (const key of [...perKey.keys()].sort()) {
    const { allowed, denied } = perKey.get(key)
    lines.push(`${key} allowed=${allowed} denied=${denied}\n`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  return lines.join('')
}
"}

