{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parseLimiterFile, LineError } from './parser.js'
import { simulate } from './simulate.js'
import { renderReplay, renderSummary } from './report.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (mode !== 'replay' && mode !== 'summary') {
  fail('usage: cli.js replay|summary')
}

const input = readFileSync(0, 'utf8')

let parsed
try {
  parsed = parseLimiterFile(input)
} catch (error) {
  if (error instanceof LineError) fail(`line ${error.line}: ${error.message}`)
  throw error
}

const verdicts = simulate(parsed)
const output = mode === 'replay' ? renderReplay(verdicts) : renderSummary(verdicts)
process.stdout.write(output)
process.exit(0)
"}

