{"file_path":"src/format.js","content":"/**
 * Rendering of a parsed document tree (see parser.js) into the two output
 * modes the CLI supports: canonical JSON and the flat "keys" listing.
 */

function cmpCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

function sortedKeys(table) {
  return [...table.order].sort(cmpCodePoint)
}

function jsonEscape(str) {
  let out = '"'
  for (const ch of str) {
    switch (ch) {
      case '"': out += '\\"'; break
      case '\\': out += '\\\\'; break
      case '\n': out += '\\n'; break
      case '\r': out += '\\r'; break
      case '\t': out += '\\t'; break
      default: {
        const code = ch.codePointAt(0)
        if (code < 0x20) {
          out += '\\u' + code.toString(16).padStart(4, '0')
        } else {
          out += ch
        }
      }
    }
  }
  out += '"'
  return out
}

function serializeValue(node, depth) {
  const pad = '  '.repeat(depth)
  const padIn = '  '.repeat(depth + 1)
  switch (node.kind) {
    case 'string':
      return jsonEscape(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.value.toString()
    case 'float':
      return String(node.value)
    case 'array': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((it) => padIn + serializeValue(it, depth + 1))
      return '[\n' + parts.join(',\n') + '\n' + pad + ']'
    }
    case 'aot': {
      if (node.tables.length === 0) return '[]'
      const parts = node.tables.map((t) => padIn + serializeValue(t, depth + 1))
      return '[\n' + parts.join(',\n') + '\n' + pad + ']'
    }
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const parts = keys.map((k) => padIn + jsonEscape(k) + ': ' + serializeValue(node.keys.get(k), depth + 1))
      return '{\n' + parts.join(',\n') + '\n' + pad + '}'
    }
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

export function toJSON(root) {
  return serializeValue(root, 0) + '\n'
}

function typeName(node) {
  switch (node.kind) {
    case 'table': return 'table'
    case 'aot': return 'array'
    case 'array': return 'array'
    default: return node.kind
  }
}

function visit(node, path, lines) {
  if (path !== null) lines.push(`${path} ${typeName(node)}\n`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) {
      visit(node.keys.get(k), path === null ? k : `${path}.${k}`, lines)
    }
  } else if (node.kind === 'aot') {
    node.tables.forEach((t, i) => visit(t, `${path}[${i}]`, lines))
  } else if (node.kind === 'array') {
    node.items.forEach((it, i) => visit(it, `${path}[${i}]`, lines))
  }
}

export function toKeys(root) {
  const lines = []
  visit(root, null, lines)
  return lines.join('')
}
"}

