{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parseElection.js'
import { runElection } from './election.js'

function usageError() {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
  usageError()
}

const input = readFileSync(0, 'utf8')

let election
try {
  election = parseElection(input)
} catch (error) {
  if (error instanceof ParseError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(2)
  }
  throw error
}

const { rounds, winner } = runElection(election.candidates, election.ballots)

const lines = []
if (mode === 'rounds') {
  for (const round of rounds) {
    const votes = round.entries.map(([name, count]) => `${name}=${count}`).join(' ')
    lines.push(`round ${round.number}: ${votes} exhausted=${round.exhausted}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  }
} else {
  lines.push(`rounds ${rounds.length}`)
}
lines.push(winner === null ? 'no winner' : `winner ${winner}`)

process.stdout.write(lines.join('\n') + '\n')
"}

