/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { CliError, normalizeReference, resolveReference } from './uri.js'

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        results.push(normalizeReference(line))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) throw new CliError('expected a base and a reference')
        const base = line.slice(0, spaceIdx)
        const ref = line.slice(spaceIdx + 1)
        results.push(resolveReference(base, ref))
      }
    } catch (err) {
      if (!(err instanceof CliError)) throw err
      process.stderr.write(`error: line ${lineNo}: ${err.message}\n`)
      process.exit(2)
    }
  }

  process.stdout.write(results.map((r) => r + '\n').join(''))
}

main()
"}

