{"file_path":"src/format.js","content":"/**
 * Renders a resolved merge (with or without the base section of a conflict
 * marker) as an array of output lines, alongside whether any conflict was
 * written.
 */
export function formatMerge(entries, includeBase) {
  const lines = []
  let conflict = false
  for (const entry of entries) {
    if (entry.type === 'stable') {
      lines.push(...entry.lines)
      continue
    }
    if (entry.kind === 'conflict') {
      conflict = true
      lines.push('<<<<<<< mine')
      lines.push(...entry.mineLines)
      if (includeBase) {
        lines.push('||||||| base')
        lines.push(...entry.baseLines)
      }
      lines.push('=======')
      lines.push(...entry.theirsLines)
      lines.push('>>>>>>> theirs')
    } else {
      lines.push(...(entry.kind === 'theirs' ? entry.theirsLines : entry.mineLines))
    }
  }
  return { lines, conflict }
}

/**
 * Renders one summary line per region, alongside whether any conflict was
 * written.
 */
export function formatRegions(entries) {
  const lines = []
  let conflict = false
  for (const entry of entries) {
    if (entry.type === 'stable') {
      lines.push(`stable ${entry.lines.length}`)
      continue
    }
    if (entry.kind === 'conflict') {
      conflict = true
      lines.push(`conflict mine=${entry.mineLines.length} base=${entry.baseLines.length} theirs=${entry.theirsLines.length}`)
    } else if (entry.kind === 'both') {
      lines.push(`both ${entry.mineLines.length}`)
    } else if (entry.kind === 'mine') {
      lines.push(`mine ${entry.mineLines.length}`)
    } else {
      lines.push(`theirs ${entry.theirsLines.length}`)
    }
  }
  return { lines, conflict }
}
"}

