 * Collects the cells a formula's AST names directly, ranges expanded,
 * restricted to addresses inside the addressable range.
 */

import { parseAddress } from './address.js'

function expandRange(fromWord, toWord) {
  const from = parseAddress(fromWord)
  const to = parseAddress(toWord)
  if (!from.valid || !to.valid) return []
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  const addrs = []
  for (let col = colMin; col <= colMax; col++) {
    for (let row = rowMin; row <= rowMax; row++) {
      addrs.push(colRowToAddr(col, row))
    }
  }
  return addrs
}

function colRowToAddr(col, row) {
  let letters = ''
  let c = col
  while (c > 0) {
    const rem = (c - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    c = Math.floor((c - 1) / 26)
  }
  return letters + String(row)
}

function walk(node, into) {
  switch (node.type) {
    case 'addr': {
      const parsed = parseAddress(node.raw)
      if (parsed.valid) into.add(parsed.addr)
      return
    }
    case 'range':
      for (const addr of expandRange(node.from, node.to)) into.add(addr)
      return
    case 'unary':
      walk(node.operand, into)
      return
    case 'bin':
      walk(node.left, into)
      walk(node.right, into)
      return
    case 'call':
      for (const arg of node.args) walk(arg, into)
      return
    case 'num':
    case 'bool':
      return
    default:
      throw new Error(`unexpected node type ${node.type}`)
  }
}

/** Returns the distinct addressable cells an AST names, unordered. */
export function collectDeps(ast) {
  const into = new Set()
  walk(ast, into)
  return into
}
"}

