{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseReference, normalize, resolve, serialize, TruncatedPercentEncodingError } from './uri.js'

class RecordError extends Error {}

function readStdin() {
  const chunks = []
  process.stdin.on('data', (chunk) => chunks.push(chunk))
  return new Promise((resolveIn, reject) => {
    process.stdin.on('end', () => resolveIn(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function splitRecords(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function processNormalize(line) {
  const comp = parseReference(line)
  normalize(comp)
  return serialize(comp)
}

function processResolve(line) {
  const spaceIdx = line.indexOf(' ')
  if (spaceIdx === -1) throw new RecordError('expected a base and a reference')
  const baseStr = line.slice(0, spaceIdx)
  const refStr = line.slice(spaceIdx + 1)

  const base = parseReference(baseStr)
  if (base.scheme === null) throw new RecordError('the base has no scheme')

  const ref = parseReference(refStr)
  const target = resolve(base, ref)
  normalize(target)
  return serialize(target)
}

async function main() {
  const args = process.argv.slice(2)
  const mode = args.length === 1 ? args[0] : null
  if (mode !== 'normalize' && mode !== 'resolve') {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exitCode = 2
    return
  }

  const input = await readStdin()
  const records = splitRecords(input)
  const process_ = mode === 'normalize' ? processNormalize : processResolve

  const outputs = []
  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    try {
      outputs.push(process_(records[i]))
    } catch (err) {
      if (err instanceof RecordError || err instanceof TruncatedPercentEncodingError) {
        process.stderr.write(`error: line ${lineNumber}: ${err.message}\n`)
        process.exitCode = 2
        return
      }
      throw err
    }
  }

  process.stdout.write(outputs.map((line) => line + '\n').join(''))
}

await main()
"}

