// A run of digits, allowing single underscores between digit groups.
const DIGITS = String.raw`\d+(?:_\d+)*`
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FRACTION = String.raw`\.${DIGITS}`
const EXPONENT = String.raw`[eE][+-]?${DIGITS}`
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:${FRACTION}(?:${EXPONENT})?|${EXPONENT})$`)

const NAME_CHAR_RE = /[A-Za-z0-9_-]/

/**
 * Parses a configuration document (already split into lines with the
 * trailing empty line dropped) into a tree of table/array/scalar nodes.
 *
 * Node shapes:
 *   { kind: 'table', map: Map<string, Node>, headerDefined: boolean }
 *   { kind: 'array-of-tables', items: Node[] }   // each item is a 'table'
 *   { kind: 'array', items: Node[] }
 *   { kind: 'string' | 'integer' | 'float' | 'boolean', value }
 */
export function parseDocument(lines) {
  const root = { kind: 'table', map: new Map(), headerDefined: false }
  let currentTable = root
  let currentPath = []

  lines.forEach((line, index) => parseLine(line, index + 1))

  return root

  function parseLine(line, lineNo) {
    const s = line
    let pos = 0

    function fail(reason) {
      throw new ConfigError(lineNo, reason)
    }

    // Skips spaces and tabs, then treats an unquoted '#' or ';' as running
    // to the end of the line, since neither ever resumes meaningful content.
    function skipWS() {
      while (pos < s.length && (s[pos] === ' ' || s[pos] === '\t')) pos++
      if (pos < s.length && (s[pos] === '#' || s[pos] === ';')) pos = s.length
    }

    function parseName() {
      skipWS()
      if (pos >= s.length) fail('expected a name')
      if (s[pos] === '"' || s[pos] === "'") return parseString().value
      const start = pos
      while (pos < s.length && NAME_CHAR_RE.test(s[pos])) pos++
      if (pos === start) fail('expected a name')
      return s.slice(start, pos)
    }

    function parseDottedName() {
      const parts = [parseName()]
      for (;;) {
        skipWS()
        if (pos < s.length && s[pos] === '.') {
          pos++
          skipWS()
          parts.push(parseName())
        } else break
      }
      return parts
    }

    function parseString() {
      const quote = s[pos]
      pos++
      let out = ''
      if (quote === '"') {
        for (;;) {
          if (pos >= s.length) fail('unterminated string')
          const ch = s[pos]
          if (ch === '"') { pos++; break }
          if (ch === '\\') {
            pos++
            if (pos >= s.length) fail('unterminated string')
            const esc = s[pos]
            if (esc === '"') { out += '"'; pos++ }
            else if (esc === '\\') { out += '\\'; pos++ }
            else if (esc === 'n') { out += '\n'; pos++ }
            else if (esc === 't') { out += '\t'; pos++ }
            else if (esc === 'r') { out += '\r'; pos++ }
            else if (esc === '0') { out += '\0'; pos++ }
            else if (esc === 'u') {
              pos++
              const hex = s.slice(pos, pos + 4)
              if (hex.length < 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) fail('invalid escape \\u')
              out += String.fromCharCode(parseInt(hex, 16))
              pos += 4
            } else {
