            pos++
          }
        }
      } else {
        for (;;) {
          if (pos >= s.length) fail('unterminated string')
          const ch = s[pos]
          if (ch === "'") { pos++; break }
          out += ch
          pos++
        }
      }
      return { kind: 'string', value: out }
    }

    function parseValue(path) {
      skipWS()
      if (pos >= s.length) fail('expected a value')
      const c = s[pos]
      if (c === '"' || c === "'") return parseString()
      if (c === '[') return parseArray(path)
      if (c === '{') return parseInlineTable(path)
      if (c === ',' || c === ']' || c === '}') fail('expected a value')
