        items.push(parseValue(path))
        skipWS()
        if (pos >= s.length) fail('unterminated array')
        if (s[pos] === ',') {
          pos++
          skipWS()
          if (pos < s.length && s[pos] === ']') { pos++; break }
          continue
        }
        if (s[pos] === ']') { pos++; break }
        fail('unterminated array')
      }
      return { kind: 'array', items }
    }

