      pos++ // consume '{'
      const table = { kind: 'table', map: new Map(), headerDefined: false }
      skipWS()
      if (pos < s.length && s[pos] === '}') { pos++; return table }
      for (;;) {
        if (pos >= s.length) fail('unterminated inline table')
        const names = parseDottedName()
        skipWS()
        if (pos >= s.length || s[pos] !== '=') fail('expected = in an inline table')
        pos++
        const value = parseValue(path.concat(names))
        assignDotted(table, names, path, value)
        skipWS()
        if (pos >= s.length) fail('unterminated inline table')
        if (s[pos] === ',') { pos++; skipWS(); continue }
        if (s[pos] === '}') { pos++; break }
        fail('unterminated inline table')
      }
      return table
    }

    function walkIntoTable(node, name, path) {
      const existing = node.map.get(name)
      if (existing === undefined) {
        const table = { kind: 'table', map: new Map(), headerDefined: false }
        node.map.set(name, table)
        return table
      }
      if (existing.kind === 'table') return existing
      if (existing.kind === 'array-of-tables') return existing.items[existing.items.length - 1]
      fail(`${path.join('.')} is not a table`)
    }

    function assignDotted(baseTable, names, prefixPath, value) {
      let node = baseTable
      for (let i = 0; i < names.length - 1; i++) {
        node = walkIntoTable(node, names[i], prefixPath.concat(names.slice(0, i + 1)))
      }
      const lastName = names[names.length - 1]
      if (node.map.get(lastName) !== undefined) {
        fail(`key ${prefixPath.concat(names).join('.')} is defined twice`)
      }
      node.map.set(lastName, value)
    }

    function parseHeader() {
      pos++ // consume the first '['
      let isArray = false
      if (pos < s.length && s[pos] === '[') { isArray = true; pos++ }
      const names = parseDottedName()
      if (pos >= s.length || s[pos] !== ']') fail('unterminated table header')
      pos++
      if (isArray) {
        skipWS()
        if (pos >= s.length || s[pos] !== ']') fail('unterminated table header')
        pos++
      }
      skipWS()
      if (pos < s.length) fail('trailing text after a table header')

      let node = root
      for (let i = 0; i < names.length - 1; i++) {
        node = walkIntoTable(node, names[i], names.slice(0, i + 1))
      }
      const lastName = names[names.length - 1]
      if (isArray) {
        let arr = node.map.get(lastName)
        if (arr === undefined) {
          arr = { kind: 'array-of-tables', items: [] }
          node.map.set(lastName, arr)
        } else if (arr.kind !== 'array-of-tables') {
          fail(`${names.join('.')} is not an array of tables`)
        }
        const table = { kind: 'table', map: new Map(), headerDefined: true }
        arr.items.push(table)
        currentTable = table
        currentPath = names.slice()
      } else {
        const existing = node.map.get(lastName)
        if (existing === undefined) {
          const table = { kind: 'table', map: new Map(), headerDefined: true }
          node.map.set(lastName, table)
          currentTable = table
          currentPath = names.slice()
        } else if (existing.kind === 'table') {
          if (existing.headerDefined) fail(`table ${names.join('.')} is defined twice`)
          existing.headerDefined = true
          currentTable = existing
          currentPath = names.slice()
        } else {
          fail(`${names.join('.')} is not a table`)
        }
      }
    }

