          if (existing.headerDefined) fail(`table ${names.join('.')} is defined twice`)
          existing.headerDefined = true
          currentTable = existing
          currentPath = names.slice()
        } else {
          fail(`${names.join('.')} is not a table`)
        }
      }
    }

    function parseAssignment() {
      const names = parseDottedName()
      skipWS()
      if (pos >= s.length || s[pos] !== '=') fail('expected key = value')
      pos++
      const value = parseValue(currentPath.concat(names))
      skipWS()
      if (pos < s.length) fail('trailing text after a value')
      assignDotted(currentTable, names, currentPath, value)
    }

    skipWS()
    if (pos >= s.length) return
    if (s[pos] === '[') parseHeader()
    else parseAssignment()
  }
}
