{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260927T230048Z/cell-xCJKLa/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import fs from 'node:fs'
import { ConfigError } from './errors.js'
import { parseDocument } from './parser.js'
import { toJSON, toKeys } from './serialize.js'

function main() {
  const mode = process.argv[2]
  if (mode !== 'json' && mode !== 'keys') {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }

  const input = fs.readFileSync(0, 'utf8')
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let root
  try {
    root = parseDocument(lines)
  } catch (error) {
    if (error instanceof ConfigError) {
      process.stderr.write(`error: ${error.message}\n`)
      process.exit(2)
    }
    throw error
  }

  process.stdout.write(mode === 'json' ? toJSON(root) : toKeys(root))
  process.exit(0)
}

main()
"}

